const major = parseInt(process.versions.node.split('.')[0], 10);

if (major < 20) {
  console.error(
    `\n❌ Este pacote requer o Node.js 20 ou superior para funcionar corretamente.\n` + `Você está usando o Node.js versão ${process.versions.node}.\n` + `Por favor, atualize para o Node.js 20 ou superior para continuar.\n`
  );
  process.exit(1);
}